                    assert item in spec['items']['enum']
                if 'pattern' in spec['items']:
                    assert re.fullmatch(spec['items']['pattern'], item)
    validator = 'complete standard-library schema checks'
else:
    jsonschema.validate(proposal, schema)
    validator = 'jsonschema.validate'
print(json.dumps({'strict_json_schema': 'passed', 'validator': validator, 'question_remains_open': not proposal['questions_resolved'], 'requires_human_review': proposal['requires_human_review']}))
